\section{Introduction}

Orbit counting is one of the oldest computational tools in group theory. Given a finite
group $G$ acting on a finite set $X$, the number of orbits $\#(X/G)$ is the number of
configurations ``up to symmetry'', and Burnside's lemma computes it as an average over
the group of a purely local quantity:
\[
  \#(X/G) \;=\; \frac{1}{|G|}\sum_{g\in G}|X^g|,\qquad
  X^g=\{x\in X: g\cdot x=x\}.
\]
The lemma is elementary --- double counting on the incidence set
$\{(g,x): g\cdot x=x\}$ combined with the orbit--stabiliser theorem --- yet it underlies
most practical enumeration up to symmetry.

The observation driving this paper is that the right-hand side is a \emph{statistical}
quantity. Endow $G$ with the uniform probability measure and consider the random variable
$A:G\to\mathbb{Z}_{\ge0}$, $A(g)=|X^g|$. Burnside's lemma says $\mathbb{E}[A]=\#(X/G)$.
It is natural to ask what the higher moments $\mathbb{E}[A^k]$ compute. The answer is
complete and clean: \textbf{they are again orbit counts, on tuples.} This turns a single
lemma into an infinite hierarchy indexed by $k$, whose low levels are classical
invariants and whose structural properties are inherited from general facts about moment
sequences.

Two features distinguish the hierarchy from a routine generalisation.
\begin{enumerate}
\item \emph{Structure transfer.} Because $o_k=\mathbb{E}[A^k]$ up to the constant $|G|$,
inequalities valid for arbitrary moment sequences of non-negative variables
(Cauchy--Schwarz, Markov, monotonicity) descend to inequalities about orbit counts, and
the factor $|G|$ cancels. The resulting statements are purely combinatorial and are not
obvious from the combinatorial side.
\item \emph{Exact Poisson behaviour.} For the full symmetric group the hierarchy has
closed form: level $k$ is the $k$-th Bell number, provided $k\le n$. Since the Bell
numbers are exactly the moments of a Poisson$(1)$ variable (Dobi\'nski's formula), the
classical asymptotic statement ``the number of fixed points of a random permutation is
asymptotically Poisson$(1)$'' is upgraded to an exact finite identity, moment by moment,
in the range $k\le n$.
\end{enumerate}

\subsection*{Notation}
$G$ is a finite group; $X$, $Y$, $X_i$ are finite $G$-sets. We write
$X^g=\{x: g\cdot x=x\}$ and $a(g)=|X^g|$. The set $X^k$ of ordered $k$-tuples, i.e.\
functions $\{1,\dots,k\}\to X$, carries the diagonal action
$g\cdot(x_1,\dots,x_k)=(gx_1,\dots,gx_k)$. We set $o_k=o_k(G,X)=\#(X^k/G)$ (the $k$-th
\emph{orbit count}) and $S_k=\sum_{g\in G}a(g)^k$ (the $k$-th \emph{moment}). Further,
$\offDiag(X)=\{(x,y)\in X\times X: x\ne y\}$, $\Stab_G(x)=\{g: g\cdot x=x\}$, and $P(k)$
is the number of set partitions of a $k$-element set (the $k$-th Bell number).

\section{Fixed points of derived actions}

\begin{lemma}[Fixed points of a power action]\label{lem:pow}
Let $I$ be a finite index set and give $X^I$ (functions $I\to X$) the pointwise action.
Then for every $g\in G$, $f\in (X^I)^g$ if and only if $f(i)\in X^g$ for all $i$;
consequently $(X^I)^g$ is in canonical bijection with $(X^g)^I$ and
\[
  \bigl|(X^I)^g\bigr| \;=\; |X^g|^{|I|}.
\]
\end{lemma}

\begin{proof}
The action is $(g\cdot f)(i)=g\cdot f(i)$, so $g\cdot f=f$ holds iff $g\cdot f(i)=f(i)$
for every $i$, by extensionality of functions. The map sending $f$ to
$i\mapsto f(i)$, with values regarded in $X^g$, is a bijection $(X^I)^g\to(X^g)^I$ with
the obvious inverse. Counting functions gives the exponential formula.
\end{proof}

\begin{lemma}[Fixed points of a product action]\label{lem:prod}
For $G$-sets $X,Y$ and $g\in G$, a pair $(x,y)$ lies in $(X\times Y)^g$ iff $x\in X^g$
and $y\in Y^g$; hence $|(X\times Y)^g| = |X^g|\cdot|Y^g|$.
\end{lemma}

\begin{lemma}[Fixed points of a family product]\label{lem:family}
For a finite family $(X_i)_{i\in I}$ of $G$-sets with the pointwise action on
$\prod_i X_i$, one has $\bigl|(\prod_i X_i)^g\bigr| = \prod_i |X_i^g|$.
\end{lemma}

Lemmas~\ref{lem:prod} and~\ref{lem:family} are proved by the same extensionality
argument as Lemma~\ref{lem:pow}, and Lemma~\ref{lem:prod} is the two-factor case of
Lemma~\ref{lem:family}.

\begin{theorem}[Burnside / Cauchy--Frobenius]\label{thm:burnside}
For a finite group $G$ acting on a finite set $X$,
$\sum_{g\in G}|X^g| = \#(X/G)\cdot|G|$.
\end{theorem}

\begin{proof}
Count $F=\{(g,x)\in G\times X: g\cdot x=x\}$ in two ways. Summing over $g$ gives
$\sum_g|X^g|$. Summing over $x$ gives $\sum_x|\Stab_G(x)|$; by orbit--stabiliser
$|\Stab_G(x)|=|G|/|Gx|$, so each orbit contributes $|G|$, and the total is
$\#(X/G)\cdot|G|$.
\end{proof}

\section{The moment identity}

\begin{theorem}[Moment identity]\label{thm:moment}
Let $G$ be a finite group acting on a finite set $X$. For every $k\ge0$,
\[
  \sum_{g\in G}|X^g|^k \;=\; \#\bigl(X^k/G\bigr)\cdot|G| .
\]
Equivalently $S_k=o_k|G|$: the $k$-th moment of the fixed-point statistic under the
uniform measure on $G$ is the number of orbits of $G$ on ordered $k$-tuples.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:burnside} to the finite $G$-set $X^k$, obtaining
$\sum_g |(X^k)^g| = \#(X^k/G)\cdot|G|$. By Lemma~\ref{lem:pow} with
$I=\{1,\dots,k\}$ we have $|(X^k)^g|=|X^g|^k$ termwise. Substituting gives the claim.
\end{proof}

\begin{theorem}[Mixed moment identity]\label{thm:mixed}
For any finite family $(X_i)_{i\in I}$ of finite $G$-sets,
\[
  \sum_{g\in G}\prod_{i\in I}|X_i^g| \;=\;
  \#\Bigl(\bigl(\textstyle\prod_i X_i\bigr)/G\Bigr)\cdot|G| .
\]
Taking all $X_i=X$ with $|I|=k$ recovers Theorem~\ref{thm:moment}.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:burnside} applied to $\prod_i X_i$, with Lemma~\ref{lem:family}
rewriting each summand.
\end{proof}

\begin{corollary}[Bilinear Burnside]\label{cor:bilinear}
For finite $G$-sets $X,Y$,
$\sum_{g\in G}|X^g|\cdot|Y^g| = \#\bigl((X\times Y)/G\bigr)\cdot|G|$.
\end{corollary}

The function $\chi_X(g)=|X^g|$ is the \emph{permutation character} of $X$: it is the
character of the linear representation on the free vector space with basis $X$, whose
matrices are permutation matrices with trace equal to the number of fixed basis vectors.
Corollary~\ref{cor:bilinear} therefore states
$\langle\chi_X,\chi_Y\rangle=\#\bigl((X\times Y)/G\bigr)$, using that permutation
characters are real-valued with $|Y^g|=|Y^{g^{-1}}|$. Thus the orbit-counting pairing is
a positive-semidefinite bilinear form on the semiring of $G$-sets, and the moment
hierarchy is its diagonal.

\subsection{Low levels}

For $k=0$ the set $X^0$ is a one-point set with trivial action, so $o_0=1$ and the
identity reads $|G|=|G|$. For $k=1$ we have $X^1\cong X$, so $o_1=\#(X/G)$ and
Theorem~\ref{thm:moment} is Burnside's lemma. For $k=2$ we have $X^2\cong X\times X$ and
$\sum_g|X^g|^2 = \#\bigl((X\times X)/G\bigr)\cdot|G|$, where
$\#\bigl((X\times X)/G\bigr)$ is by definition the \emph{rank} of the permutation action.

\begin{proposition}[Transitivity from the first moment]\label{prop:trans}
If $X\ne\emptyset$, the action is transitive if and only if $\sum_{g\in G}|X^g|=|G|$.
\end{proposition}

\begin{proof}
By Theorem~\ref{thm:burnside} the sum equals $\#(X/G)\cdot|G|$, and $\#(X/G)\ge1$ as
$X\ne\emptyset$. Transitivity is exactly $\#(X/G)=1$. Conversely, if the sum is $|G|$ and
$\#(X/G)\ge2$ then $2|G|\le|G|$, a contradiction.
\end{proof}

\section{The rank level in detail}

Throughout, $\offDiag(X)$ is $G$-invariant because $G$ acts by bijections.

\begin{lemma}\label{lem:offdiag}
For every $g$, $\;\bigl|\offDiag(X)^g\bigr| + |X^g| = |X^g|^2$.
\end{lemma}

\begin{proof}
A pair $(x,y)$ with $x\ne y$ is fixed by $g$ iff both coordinates are, so
$\offDiag(X)^g=\offDiag(X^g)$. For any finite set $F$ the ordered pairs from $F$ split
into the diagonal (a copy of $F$) and the rest, so $|\offDiag(F)|+|F|=|F|^2$.
\end{proof}

\begin{theorem}[Rank splitting]\label{thm:ranksplit}
$\#\bigl((X\times X)/G\bigr) = \#(X/G) + \#\bigl(\offDiag(X)/G\bigr)$.
\end{theorem}

\begin{proof}
Multiply both sides by $|G|$ and apply Theorem~\ref{thm:burnside} three times: the left
side becomes $\sum_g|X^g|^2$ (via Theorem~\ref{thm:moment} at $k=2$) and the right side
becomes $\sum_g|X^g|+\sum_g|\offDiag(X)^g|$. Lemma~\ref{lem:offdiag} equates them
termwise; cancel the positive factor $|G|$.
\end{proof}

\begin{corollary}\label{cor:rank2}
If $|X|\ge2$ and the action is transitive, then $\sum_{g\in G}|X^g|^2\ge 2|G|$.
\end{corollary}

\begin{proof}
Transitivity gives $\#(X/G)=1$, and $|X|\ge2$ makes $\offDiag(X)$ non-empty, so its
orbit count is at least $1$. Apply Theorem~\ref{thm:ranksplit} and multiply by $|G|$.
\end{proof}

\begin{theorem}[Second-moment characterisation of $2$-transitivity]\label{thm:2trans}
Suppose $|X|\ge2$. Then $G$ acts transitively on $X$ \emph{and} transitively on
$\offDiag(X)$ if and only if $\sum_{g\in G}|X^g|^2 = 2|G|$.
\end{theorem}

\begin{proof}
By Theorems~\ref{thm:moment} and~\ref{thm:ranksplit} the left-hand side equals
$\bigl(\#(X/G)+\#(\offDiag(X)/G)\bigr)|G|$. Both counts are at least $1$ since both sets
are non-empty. Hence the sum equals $2|G|$ iff both counts are $1$, i.e.\ iff both
actions are transitive.
\end{proof}

\begin{remark}[A tempting false statement]
Transitivity alone does \emph{not} force rank $2$. The dihedral group of order $8$ acting
on the vertices of a square is transitive, but its fixed-point profile is
$(4,0,0,0,2,2,0,0)$, so $\sum_g|X^g|^2 = 24 = 3\cdot 8$: the rank is $3$, the orbits on
ordered pairs being the diagonal, the adjacent pairs and the opposite pairs.
Theorem~\ref{thm:2trans} carries the off-diagonal transitivity hypothesis for exactly
this reason.
\end{remark}

\subsection{Suborbits: the local form of the second moment}

\begin{theorem}[Rank equals the number of suborbits]\label{thm:suborbits}
Let $G$ act transitively on $X$, let $x_0\in X$ and $H=\Stab_G(x_0)$. Then
\[
  \#\bigl((X\times X)/G\bigr)\;=\;\#(X/H).
\]
\end{theorem}

\begin{proof}
Define $\Phi:X/H\to (X\times X)/G$ by $\Phi(Hy)=G\cdot(x_0,y)$. It is well defined: if
$y'=h\cdot y$ with $h\in H$ then $h\cdot(x_0,y)=(x_0,y')$. It is injective: if
$g\cdot(x_0,y')=(x_0,y)$ then $g\in H$ and $g\cdot y'=y$, so $Hy=Hy'$. It is surjective:
given $(x,y)$, transitivity provides $a$ with $a\cdot x_0=x$, and then
$a^{-1}\cdot(x,y)=(x_0,a^{-1}y)$.
\end{proof}

\begin{corollary}\label{cor:suborbits}
For a transitive action of a finite $G$ on a finite $X$ with $x_0\in X$ and
$H=\Stab_G(x_0)$,
\[
  \sum_{g\in G}|X^g|^2 = \#(X/H)\cdot|G|,
\]
and if moreover $|X|\ge2$ then $\#(X/H) = 1 + \#\bigl(\offDiag(X)/G\bigr)$.
\end{corollary}

\begin{proof}
Combine Theorem~\ref{thm:moment} at $k=2$ with Theorem~\ref{thm:suborbits}; for the
second claim combine Theorem~\ref{thm:suborbits} with Theorem~\ref{thm:ranksplit} and
$\#(X/G)=1$.
\end{proof}

\section{Structural properties of the hierarchy}

Throughout this section $o_k=\#(X^k/G)$ and $S_k=\sum_g|X^g|^k=o_k|G|$.

\begin{proposition}[Divisibility]\label{prop:div}
For every $k$, $|G|$ divides $S_k=\sum_{g\in G}|X^g|^k$.
\end{proposition}

\begin{proof}
Immediate from Theorem~\ref{thm:moment}, since $o_k$ is a non-negative integer.
\end{proof}

\begin{proposition}
$o_0=1$; and if $X\ne\emptyset$ then $o_k\ge1$ for every $k$.
\end{proposition}

\begin{theorem}[Monotonicity]\label{thm:mono}
For every $k\ge1$, $o_k\le o_{k+1}$.
\end{theorem}

\begin{proof}
For each $g$, either $|X^g|=0$, whence $|X^g|^k=|X^g|^{k+1}=0$ (this uses $k\ge1$, since
$0^0=1$), or $|X^g|\ge1$, whence $|X^g|^k\le|X^g|^{k+1}$. Summing gives
$o_k|G|\le o_{k+1}|G|$; cancel $|G|>0$.
\end{proof}

The hypothesis $k\ge1$ is necessary: for $X=\emptyset$ one has $o_0=1>0=o_1$.

\begin{lemma}[Pointwise AM--GM]\label{lem:amgm}
For non-negative integers $x,y$ and any $k\ge0$,
$\;2x^{k+1}y^{k+1}\le x^ky^{k+2}+y^kx^{k+2}$.
\end{lemma}

\begin{proof}
From $(x-y)^2\ge0$ we get $2xy\le x^2+y^2$; multiply by $x^ky^k\ge0$ and expand.
\end{proof}

\begin{lemma}[Cauchy--Schwarz for moment sequences]\label{lem:cs}
Let $S$ be a finite index set and $a:S\to\mathbb{Z}_{\ge0}$. For every $k\ge0$,
\[
  \Bigl(\sum_{i\in S}a_i^{k+1}\Bigr)^2 \;\le\;
  \Bigl(\sum_{i\in S}a_i^{k}\Bigr)\Bigl(\sum_{i\in S}a_i^{k+2}\Bigr).
\]
\end{lemma}

\begin{proof}
Expand both sides as double sums: the left is $\sum_{i,j}a_i^{k+1}a_j^{k+1}$, the right
is $\sum_{i,j}a_i^ka_j^{k+2}$. Doubling the right and symmetrising the summation indices
gives $\sum_{i,j}\bigl(a_i^ka_j^{k+2}+a_j^ka_i^{k+2}\bigr)$, which dominates
$\sum_{i,j}2a_i^{k+1}a_j^{k+1}$ termwise by Lemma~\ref{lem:amgm}. Halving gives the
claim; this is Cauchy--Schwarz for the vectors $(a_i^{k/2})$ and $(a_i^{(k+2)/2})$,
arranged to stay inside the integers.
\end{proof}

\begin{theorem}[Log-convexity of the orbit hierarchy]\label{thm:logconvex}
For every $k\ge0$, $\;o_{k+1}^2 \le o_k\,o_{k+2}$.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:cs} with $S=G$ and $a(g)=|X^g|$ gives $S_{k+1}^2\le S_kS_{k+2}$.
Substituting $S_j=o_j|G|$ and cancelling $|G|^2>0$ gives the claim.
\end{proof}

\begin{theorem}[Superexponential growth]\label{thm:growth}
If $X\ne\emptyset$, then $o_1o_k\le o_{k+1}$ for all $k\ge0$, and hence
$o_1^{\,k}\le o_k$.
\end{theorem}

\begin{proof}
Induction on $k$. For $k=0$: $o_1\cdot1\le o_1$. Assuming $o_1o_n\le o_{n+1}$,
\[
  (o_1o_{n+1})o_n = (o_1o_n)o_{n+1} \le o_{n+1}^2 \le o_no_{n+2},
\]
using the inductive hypothesis and Theorem~\ref{thm:logconvex}. Since $X\ne\emptyset$
gives $o_n>0$, cancel $o_n$. The second statement follows by a further induction:
$o_1^{n+1}=o_1o_1^n\le o_1o_n\le o_{n+1}$.
\end{proof}

Thus $\#(X/G)^k\le\#(X^k/G)$: the naive lower bound obtained by remembering only which
orbit each coordinate lies in, proved by pure moment manipulation.

\begin{theorem}[Sandwich]\label{thm:sandwich}
For all $k$, $\;|X|^k \le |G|\,o_k \le |G|\,|X|^k$.
\end{theorem}

\begin{proof}
The identity element fixes everything, so $|X|^k$ is one term of the non-negative sum
$S_k=|G|o_k$. Conversely $|X^g|\le|X|$ for all $g$, so $S_k\le|G||X|^k$.
\end{proof}

\begin{theorem}[Moment / Markov bound]\label{thm:markov}
For all $t,k\ge0$,
\[
  \#\{g\in G: |X^g|\ge t\}\cdot t^k \;\le\; \#\bigl(X^k/G\bigr)\cdot|G| .
\]
\end{theorem}

\begin{proof}
Restrict $S_k=\sum_g|X^g|^k$ to $T=\{g:|X^g|\ge t\}$; every remaining term is at least
$t^k$, so $|T|t^k\le S_k=o_k|G|$.
\end{proof}

\begin{theorem}[Cauchy--Schwarz for orbit counts]\label{thm:csorbits}
For finite $G$-sets $X$ and $Y$,
\[
  \#\bigl((X\times Y)/G\bigr)^2 \;\le\;
  \#\bigl((X\times X)/G\bigr)\cdot\#\bigl((Y\times Y)/G\bigr).
\]
\end{theorem}

\begin{proof}
Put $a(g)=|X^g|$, $b(g)=|Y^g|$. Corollary~\ref{cor:bilinear} gives
$\#((X\times Y)/G)|G|=\sum_g a(g)b(g)$, and Theorem~\ref{thm:moment} at $k=2$ gives
$\#((X\times X)/G)|G|=\sum_g a(g)^2$ and likewise for $Y$. Apply
$(\sum ab)^2\le(\sum a^2)(\sum b^2)$ and cancel $|G|^2$.
\end{proof}

\subsection{An extreme case: the regular action}

\begin{theorem}[Regular action]\label{thm:regular}
Let $G$ act on itself by left translation and let $k\ge1$. Then
$o_k(G,G)=|G|^{k-1}$.
\end{theorem}

\begin{proof}
For the regular action $g\cdot x=x$ forces $g=1$, so $|G^g|=0$ for $g\ne1$ and
$|G^1|=|G|$. Hence $S_k=|G|^k$ (only the identity term survives, using $k\ge1$) and
$o_k=S_k/|G|=|G|^{k-1}$.
\end{proof}

The regular action saturates the lower end of Theorem~\ref{thm:sandwich}, since
$|G|o_k=|G|^k=|X|^k$ exactly, and it is the extreme case of Theorem~\ref{thm:growth}:
$o_1=1$ and the growth is exactly geometric with ratio $|G|$.

\section{The symmetric group: kernels, Bell numbers and exact Poisson moments}

Let $|X|=n$ and let $G=\Sym(X)$ act naturally, so that $|X^\sigma|=|\fix\sigma|$.

\begin{definition}[Kernel of a tuple]
For $f:\{1,\dots,k\}\to X$, the \emph{kernel} $\ker f$ is the equivalence relation on
$\{1,\dots,k\}$ given by $i\sim j\iff f(i)=f(j)$; equivalently, the partition of
$\{1,\dots,k\}$ into the fibres of $f$.
\end{definition}

\begin{theorem}[Kernel classification of orbits]\label{thm:kernel}
Two $k$-tuples $f,f':\{1,\dots,k\}\to X$ lie in the same $\Sym(X)$-orbit if and only if
$\ker f=\ker f'$.
\end{theorem}

\begin{proof}
If $f'=\sigma\circ f$ for a bijection $\sigma$, then
$f'(i)=f'(j)\iff f(i)=f(j)$, so the kernels agree. Conversely, if $\ker f=\ker f'$ then
$f(i)\mapsto f'(i)$ is a well-defined bijection from the image of $f$ onto the image of
$f'$: well defined because $f(i)=f(j)$ forces $f'(i)=f'(j)$, injective by the converse
implication. The two images have equal cardinality, hence so do their complements in $X$;
choosing any bijection between the complements and gluing produces a permutation $\sigma$
of $X$ with $\sigma\circ f=f'$.
\end{proof}

\begin{theorem}[Realisability]\label{thm:realise}
If $k\le n$, every equivalence relation $r$ on $\{1,\dots,k\}$ is $\ker f$ for some
$f:\{1,\dots,k\}\to X$.
\end{theorem}

\begin{proof}
The quotient $\{1,\dots,k\}/r$ has at most $k\le n=|X|$ classes, so there is an injection
$\iota$ from the classes into $X$; put $f(i)=\iota([i])$. Then
$f(i)=f(j)\iff[i]=[j]\iff i\sim_r j$.
\end{proof}

\begin{corollary}[Orbits on tuples are set partitions]\label{cor:bell}
For $k\le n$, $\;o_k(\Sym(X),X) = P(k)$, the $k$-th Bell number.
\end{corollary}

\begin{proof}
Theorem~\ref{thm:kernel} makes ``orbit $\mapsto$ kernel'' a well-defined injection into
the set of equivalence relations on $\{1,\dots,k\}$, and Theorem~\ref{thm:realise} makes
it surjective when $k\le n$.
\end{proof}

\begin{theorem}[Poisson moment theorem]\label{thm:poisson}
Let $|X|=n$ and $k\le n$. Then
\[
  \sum_{\sigma\in\Sym(X)} |\fix\sigma|^{\,k} \;=\; P(k)\cdot n! ,
\]
i.e.\ $\mathbb{E}\bigl[|\fix\sigma|^k\bigr]=P(k)$ for a uniformly random permutation
$\sigma$ of an $n$-set.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:moment} with $G=\Sym(X)$, $|G|=n!$, and $o_k=P(k)$ by
Corollary~\ref{cor:bell}.
\end{proof}

\begin{remark}[Why ``Poisson'']
Dobi\'nski's formula $P(k)=e^{-1}\sum_{m\ge0}m^k/m!$ says that the Bell numbers are the
raw moments of a Poisson random variable of mean $1$. Theorem~\ref{thm:poisson}
therefore states that the fixed-point count of a random permutation of an $n$-set agrees
with a Poisson$(1)$ variable in all moments up to order $n$ --- exactly, not
asymptotically.
\end{remark}

\begin{remark}[Sharpness of $k\le n$]\label{rem:sharp}
For $n=3$ the fixed-point counts over the six permutations are $3,1,1,1,0,0$, giving
$S_1=6=1\cdot3!$, $S_2=12=2\cdot3!$ and $S_3=30=5\cdot3!$, matching
$P(1),P(2),P(3)=1,2,5$. At $k=4$, however, $S_4=84=14\cdot3!$ while $P(4)=15$: the
partition of $\{1,2,3,4\}$ into four singletons is not realisable by a $4$-tuple from a
$3$-set. Beyond $k=n$ the hierarchy counts partitions into at most $n$ blocks.
\end{remark}

\begin{theorem}[Low levels for $\Sym(X)$]
For $n\ge1$, $\sum_\sigma|\fix\sigma| = n!$; for $n\ge2$,
$\sum_\sigma|\fix\sigma|^2 = 2\cdot n!$.
\end{theorem}

\begin{proof}
The natural action is transitive, so Proposition~\ref{prop:trans} gives the first claim.
For the second, $\Sym(X)$ is transitive on ordered pairs of distinct points: given
$a\ne b$ and $c\ne d$, let $\sigma_1$ be the transposition $(a\;c)$ and
$\sigma_2$ the transposition $(\sigma_1(b)\;d)$; since $\sigma_1(b)\ne c$, the
permutation $\sigma_2\sigma_1$ fixes $c$ as the image of $a$ and sends $b$ to $d$. Now
apply Theorem~\ref{thm:2trans}.
\end{proof}

\begin{theorem}[Log-convexity of the Bell numbers]\label{thm:bellconvex}
For all $k\ge0$, $\;P(k+1)^2 \le P(k)\,P(k+2)$.
\end{theorem}

\begin{proof}
Choose $n\ge k+2$ and apply Theorem~\ref{thm:logconvex} to the natural action of
$\Sym(X)$ on an $n$-set; by Corollary~\ref{cor:bell} the three levels involved are
$P(k)$, $P(k+1)$, $P(k+2)$.
\end{proof}

The initial values $P(0),\dots,P(5)=1,1,2,5,15,52$ satisfy $1\le2$, $4\le5$, $25\le30$,
$225\le260$. A classical inequality about set partitions has been obtained as
Cauchy--Schwarz for the moments of a random permutation's fixed-point count.

Running the identity backwards computes partition counts: for $n=3$ enumeration gives
$\sum_\sigma|\fix\sigma|^3=30$, hence $P(3)=30/6=5$; for $n=4$ the fixed-point counts are
$4$ once, $2$ for six transpositions, $1$ for eight $3$-cycles and $0$ otherwise, giving
$\sum_\sigma|\fix\sigma|^4=256+96+8=360$ and $P(4)=360/24=15$.

\section{Algorithms}

\begin{algorithm}[Moment ladder from a fixed-point profile]
Given the multiset $\{a(g):g\in G\}$ and a bound $K$, compute $S_k=\sum_g a(g)^k$ and set
$o_k=S_k/|G|$, an exact integer division by Proposition~\ref{prop:div}. Cost:
$O(|G|K)$ arithmetic operations once the profile is known, versus $\Theta(|X|^k)$ for
direct orbit enumeration on $k$-tuples. The profile itself costs $O(|G||X|)$ by
enumeration, or can be read off from a cycle-index computation.
\end{algorithm}

\begin{algorithm}[Rank and $2$-transitivity test]
Compute $S_1$ and $S_2$ from the profile. The action is transitive iff $S_1=|G|$; the
rank is $S_2/|G|$; the action is $2$-transitive iff $S_2=2|G|$ (assuming $|X|\ge2$). By
Theorem~\ref{thm:ranksplit} the number of orbits on distinct ordered pairs is
$S_2/|G|-S_1/|G|$. No search over the $|X|^2$ pairs is required.
\end{algorithm}

\begin{algorithm}[Certified structural checks]
Given a computed ladder, verify $o_0=1$, $o_k\le o_{k+1}$ for $k\ge1$,
$o_{k+1}^2\le o_ko_{k+2}$, $o_1^k\le o_k$, and $|X|^k\le|G|o_k\le|G||X|^k$. These are
guaranteed by Theorems~\ref{thm:mono}, \ref{thm:logconvex}, \ref{thm:growth}
and~\ref{thm:sandwich}, so a violation certifies an implementation error.
\end{algorithm}

\begin{algorithm}[Bell numbers from a symmetric group]
For $k\le n$, use the exact profile
$\#\{\sigma:|\fix\sigma|=m\}=\binom{n}{m}D_{n-m}$, with $D$ the derangement numbers, and
output $P(k)=S_k/n!$ by Theorem~\ref{thm:poisson}. This costs $O(n+k\log k)$ big-integer
operations and gives an independent route to the Bell numbers.
\end{algorithm}

\section{Applications and interpretation}

\emph{Enumeration up to symmetry, refined.} Classical applications of Burnside's lemma
--- necklaces, colourings, chemical isomers, switching classes of graphs --- live at
level $k=1$. The hierarchy shows that the same input data answers questions about ordered
tuples of configurations up to simultaneous symmetry at no extra modelling cost; the rank
$o_2$ measures how many essentially different relative positions two configurations can
have.

\emph{Permutation group theory.} Rank, subdegrees and suborbits are the standard first
invariants of a transitive permutation group. Theorem~\ref{thm:2trans} packages
$2$-transitivity as one quadratic identity in the fixed-point profile, and
Theorem~\ref{thm:suborbits} makes level $2$ a stabiliser computation.

\emph{Representation theory.} By Corollary~\ref{cor:bilinear},
$o_2=\langle\chi_X,\chi_X\rangle$ is the sum of squares of the multiplicities of the
irreducible constituents of the permutation representation. Hence $o_2=2$ is equivalent
to the representation splitting as the trivial representation plus one irreducible ---
the classical irreducibility of the standard representation of a $2$-transitive action.

\emph{Probabilistic combinatorics.} Theorem~\ref{thm:poisson} gives exact moments for the
fixed-point statistic of a random permutation, and Theorem~\ref{thm:markov} turns any
level of the hierarchy into a tail bound, providing a combinatorial substitute for
probabilistic machinery in the finite regime.

\section{Discussion}

The moment identity says that the map $Z\mapsto\#(Z/G)$ is a linear functional on the
Burnside semiring of finite $G$-sets, computed by averaging the permutation character,
and that the semiring multiplication corresponds to multiplication of characters. The
hierarchy is the diagonal subsemiring generated by a single $G$-set. Monotonicity,
log-convexity and growth are statements about one character multiplied by itself, and the
group order cancels because the functional is an average. The bilinear identity explains
why level $2$ is representation-theoretic: it is a genuine inner product, so
Cauchy--Schwarz is available. The symmetric-group case is extremal: the hierarchy
saturates at the Bell numbers, the largest values compatible with kernel classification.

Two limitations deserve mention. The hierarchy is not a complete invariant of a $G$-set:
non-isomorphic $G$-sets may share a permutation character (Gassmann equivalence) and thus
have identical ladders. And the range $k\le n$ in the symmetric-group results is
essential rather than technical (Remark~\ref{rem:sharp}); beyond it the orbit count is
the number of partitions into at most $n$ blocks, and the clean Poisson statement
degrades accordingly.

\section{Future directions}

\textbf{Bell recurrence via orbit surgery.} The recurrence
$B_{n+1}=\sum_i\binom{n}{i}B_{n-i}$ should be the orbit-counting shadow of a surgery on
$(n+1)$-tuples: split off the block containing the last coordinate. The kernel
classification already identifies orbits with partitions, so only the block-decomposition
bijection is missing.

\textbf{Stirling transform of the hierarchy.} The $k$-th level decomposes over kernel
types, $o_k=\sum_j S(k,j)d_j$, with $S(k,j)$ Stirling numbers of the second kind and
$d_j$ the number of orbits on \emph{injective} $j$-tuples. This generalises the $k=2$
splitting $o_2=o_1+\#(\offDiag/G)$.

\textbf{Multiplicity-free actions from moment saturation.} Since $o_2$ is the sum of
squared multiplicities in the permutation representation, $o_2$ equal to the number of
irreducible constituents characterises multiplicity-free (Gelfand pair) actions; higher
levels should detect finer decomposition data of tensor powers.

\textbf{Sharpness and equality analysis.} The regular action gives $o_k=|G|^{k-1}$ and
hence equality in log-convexity; classifying actions with exactly log-linear hierarchies
would sharpen the growth theory.

\textbf{Effective tail bounds.} Optimising the Markov bound over $k$ for concrete
families (symmetric, alternating, classical groups of Lie type) should reproduce and
possibly sharpen known bounds on elements with many fixed points.

\section{Summary of results}

\begin{enumerate}
\item \textbf{Moment identity.} $\sum_{g\in G}|X^g|^k = \#(X^k/G)\cdot|G|$ for all
$k\ge0$.
\item \textbf{Mixed moment identity.}
$\sum_{g\in G}\prod_i|X_i^g| = \#\bigl((\prod_iX_i)/G\bigr)\cdot|G|$; the two-factor case
identifies the permutation-character inner product with orbit counting on the product.
\item \textbf{Level $k=2$.} Rank splitting; the criterion $\sum_g|X^g|^2=2|G|$ for
$2$-transitivity; rank equals the number of suborbits of a point stabiliser for
transitive actions.
\item \textbf{Structure.} Monotonicity for $k\ge1$; log-convexity; superexponential
growth $o_1^k\le o_k$; the sandwich $|X|^k\le|G|o_k\le|G||X|^k$; divisibility of every
moment by $|G|$; a Markov bound; Cauchy--Schwarz for orbit counts.
\item \textbf{Regular action.} $o_k(G,G)=|G|^{k-1}$ for $k\ge1$.
\item \textbf{Symmetric group.} Kernel classification; $o_k=P(k)$ for $k\le n$; the exact
Poisson moment theorem; log-convexity of the Bell numbers.
\end{enumerate}

